  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Checks whether a connected path from the source to the sink exists by following pipe connectivity from the source’s pointing direction.
   * Algorithm:
   * 1. Start from sourceCell.
   * 2. Move one step in sourceCell.pointingTo.
   * 3. If the adjacent cell is the sinkCell, return true.
   * 4. If the adjacent cell is not a pipe, return false.
   * 5. Traverse the board through connected pipes using pipe.getConnections().
   * 6. From each pipe, continue only through directions that match a neighboring pipe’s opposite direction.
   * 7. Return true immediately when sinkCell is reached.
   * 8. Return false if traversal finishes without reaching sinkCell.
   * Related Features: sourceCell, sinkCell, cell
   * Related Classes: Coordinate, Pipe, TerminationCell, Direction
   * Input: None.
   * Output: true if a connected path exists from sourceCell to sinkCell; otherwise false.
   * Pre-condition: sourceCell, sinkCell, and the board cells have been initialized.
   * Post-condition: No map state is changed.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean checkPath()
  {
    if (cell == null || getSourceCell() == null || getSinkCell() == null)
    {
      return false;
    }

    Coordinate start = getSourceCell().getCoord();
    Direction dir = getSourceCell().getPointingTo();
    int r = start.getRow();
    int c = start.getCol();
    if (dir == Direction.UP) r--;
    else if (dir == Direction.DOWN) r++;
    else if (dir == Direction.LEFT) c--;
    else if (dir == Direction.RIGHT) c++;

    if (r < 0 || c < 0 || r >= cell.length || c >= cell[r].length)
    {
      return false;
    }

    Cell current = cell[r][c];
    if (current == getSinkCell())
    {
      return true;
    }
    if (!(current instanceof FillableCell) || ((FillableCell)current).getPipe() == null)
    {
      return false;
    }

    BasicEList<Coordinate> visited = new BasicEList<Coordinate>();
    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    Coordinate first = Pa19Factory.eINSTANCE.createCoordinate();
    first.setRow(r);
    first.setCol(c);
    queue.add(first);
    visited.add(first);

    while (!queue.isEmpty())
    {
      Coordinate cur = queue.poll();
      Cell curCell = cell[cur.getRow()][cur.getCol()];
      Pipe pipe = ((FillableCell)curCell).getPipe();
      for (Direction d : pipe.getConnections())
      {
        int nr = cur.getRow();
        int nc = cur.getCol();
        if (d == Direction.UP) nr--;
        else if (d == Direction.DOWN) nr++;
        else if (d == Direction.LEFT) nc--;
        else if (d == Direction.RIGHT) nc++;

        if (nr < 0 || nc < 0 || nr >= cell.length || nc >= cell[nr].length)
        {
          continue;
        }

        Cell next = cell[nr][nc];
        if (next == getSinkCell())
        {
          return true;
        }

        if (!(next instanceof FillableCell))
        {
          continue;
        }

        Pipe nextPipe = ((FillableCell)next).getPipe();
        if (nextPipe == null)
        {
          continue;
        }

        Direction opp = opposite(d);
        boolean ok = false;
        for (Direction nd : nextPipe.getConnections())
        {
          if (nd == opp)
          {
            ok = true;
            break;
          }
        }
        if (!ok)
        {
          continue;
        }

        Coordinate ncCoord = Pa19Factory.eINSTANCE.createCoordinate();
        ncCoord.setRow(nr);
        ncCoord.setCol(nc);
        if (!visited.contains(ncCoord))
        {
          visited.add(ncCoord);
          queue.add(ncCoord);
        }
      }
    }

    return false;
  }

